import{_ as o,o as i,c as a,a2 as c}from"./chunks/framework.BG8d4IEm.js";const w=JSON.parse('{"title":"web_dev","description":"","frontmatter":{"title":"web_dev","tags":"web_dev","birth":"2017-07-12T00:00:00.000Z","modified":"2017-07-12T00:00:00.000Z"},"headers":[],"relativePath":"projects/wechat/web_dev.md","filePath":"projects/wechat/web_dev.md"}'),l={name:"projects/wechat/web_dev.md"};function t(d,e,r,s,p,n){return i(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="web-dev" tabindex="-1">web_dev <a class="header-anchor" href="#web-dev" aria-label="Permalink to &quot;web_dev&quot;">​</a></h1><p><strong>前言:微信官方文档网页开发说明</strong></p><hr><h2 id="网页开发" tabindex="-1"><a href="https://mp.weixin.qq.com/wiki?t=resource/res_main&amp;id=mp1483682025_enmey" target="_blank" rel="noreferrer">网页开发</a> <a class="header-anchor" href="#网页开发" aria-label="Permalink to &quot;[网页开发](https://mp.weixin.qq.com/wiki?t=resource/res_main&amp;id=mp1483682025_enmey)&quot;">​</a></h2><p>浏览器内核为 <code>WKWebview</code> 或 <code>UIWebview</code> 微信 6.5.3 以后支持手动切换内核.</p><ol><li>微信主页点击右上角加好</li><li>点击添加朋友</li><li>输入 <code>:switchweb</code></li><li>会给出提示框显示当前使用内核为 <code>UIWebview</code> 还是 <code>WKWebview</code></li></ol><blockquote><p>在 WKebview 界面下会出现闪烁问题,</p></blockquote><p>查看当前内核</p><ul><li>进入任意网页下拉网页</li><li>点击任意网页右上角菜单</li></ul><p>显示 <code>此网页由</code> 为 <code>WKWebview</code> ,<code>网页由</code> 为 <code>UIWebview</code></p><p>利用 <code>window.__wxjs_is_wkwebview</code> 为真使用 <code>WKWebview</code></p><p><strong>经验在 ios 特性时,使用 safri 来进行类比</strong></p><p>微信在 <code>WKWebview</code> 中注入了 <code>JSBridge</code> 对象. 重点关注如下问题</p><ul><li>页面功能</li><li>页面屏幕适配</li><li>利用微信按钮点击返回行为</li><li>页面 js 缘分兼容性</li><li>JSAPI 兼容性</li><li>cookie 和 localstroage 存储</li><li>cache-control 缓存机制设定</li></ul><h3 id="jsapi" tabindex="-1">jsapi <a class="header-anchor" href="#jsapi" aria-label="Permalink to &quot;jsapi&quot;">​</a></h3><ul><li>不支持 <code>cache</code> api.</li><li>wx.config 失败</li></ul><p>ios 微信 6.5.1 以下,使用 HTMl5 <code>Histroy API</code></p><ul><li><code>pushState</code></li><li><code>popState</code></li><li><code>replaceState</code> 控制页面导航时(单页面应用) 同时使用 <code>JSSDK</code> wx.config 授权 jsapi 出现无权限而调用失败</li></ul><p>ios 微信 6.5.2 之后,可能出现此问题</p><blockquote><p>注意使用 jssdk 时开启调试模式简化调试步骤</p></blockquote><h3 id="cookie-和-localstorage" tabindex="-1">cookie 和 localStorage <a class="header-anchor" href="#cookie-和-localstorage" aria-label="Permalink to &quot;cookie 和 localStorage&quot;">​</a></h3><p>退出微信会被清空.</p><p>需保证服务端设置了 <code>cache control</code> 后再进行 html 页面缓存设置.</p>',23)])])}const b=o(l,[["render",t]]);export{w as __pageData,b as default};
